'use strict';

// Wave entry point. The Python driver owns staging and server lifetimes; this
// file also runs the two real Edge visits requested by that driver. No product
// implementation is needed to author or syntax-check this source locally.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {spawnSync} = require('node:child_process');

const PYTHON = 'C:\\Users\\oren\\AppData\\Local\\Programs\\Python\\Python312\\python.exe';
const PLAYWRIGHT = 'C:\\Users\\oren\\codex-harness\\ui\\node_modules\\.pnpm\\playwright-core@1.59.1\\node_modules\\playwright-core';
const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';

// Match the meaning of an accessible action, without demanding a particular
// label, CSS class, ID, markup layout, or one-unit consumption implementation.
const CONSUME_ACTION = /consume|use\b|take\b|decrease|decrement|subtract|minus|^\s*[−-]\s*$/i;

async function itemScope(page, name) {
  const label = page.getByText(name, {exact: true}).first();
  await label.waitFor({state: 'visible'});
  let scope = label;
  // Walk outward from the visible item name. Controls themselves are always
  // located by semantic role; no private product selectors are consumed.
  for (let depth = 0; depth < 10; depth++) {
    const action = scope.getByRole('button', {name: CONSUME_ACTION});
    if (await action.count() === 1) return {scope, action};
    scope = scope.locator('..');
  }
  const names = await page.getByRole('button').allTextContents();
  throw new Error(`Cannot identify a unique accessible consumption action for ${name}; buttons: ${JSON.stringify(names)}`);
}

async function visibleQuantity(scope, quantity) {
  const number = new RegExp(`(?:^|\\D)${quantity}(?:\\D|$)`);
  const deadline = Date.now() + 8000;
  let rendered = '';
  do {
    rendered = await scope.innerText();
    if (number.test(rendered)) return rendered;
    await new Promise(resolve => setTimeout(resolve, 80));
  } while (Date.now() < deadline);
  throw new Error(`Quantity ${quantity} is not visible in the imported item: ${rendered}`);
}

async function browserVisit(phase, base, expectedFile) {
  assert.ok(['consume', 'persisted'].includes(phase), 'Unknown browser check phase');
  assert.ok(process.env.SELDON_EVIDENCE_DIR, 'SELDON_EVIDENCE_DIR is required');
  const evidence = path.resolve(process.env.SELDON_EVIDENCE_DIR);
  fs.mkdirSync(evidence, {recursive: true});
  const expected = JSON.parse(fs.readFileSync(expectedFile, 'utf8'));
  const {chromium} = require(PLAYWRIGHT);
  const requests = [];
  const external = [];
  const errors = [];
  let browser;
  let page;
  let result;
  try {
    browser = await chromium.launch({headless: true, executablePath: EDGE});
    const context = await browser.newContext({viewport: {width: 1365, height: 900}});
    context.setDefaultTimeout(8000);
    context.on('request', request => {
      requests.push({method: request.method(), url: request.url()});
    });
    // Block and fail any attempted external request, so verification itself
    // cannot let the product contact another host.
    await context.route('**/*', async route => {
      if (new URL(route.request().url()).origin !== base) {
        external.push(route.request().url());
        await route.abort('blockedbyclient');
      } else {
        await route.continue();
      }
    });
    context.on('page', opened => {
      opened.on('pageerror', error => errors.push(error.message));
      opened.on('websocket', socket => {
        const address = new URL(socket.url());
        address.protocol = address.protocol === 'wss:' ? 'https:' : 'http:';
        if (address.origin !== base) external.push(socket.url());
      });
    });
    page = await context.newPage();
    await page.goto(base + '/', {waitUntil: 'networkidle'});
    assert.equal(await page.title(), 'ShelfLife');
    await page.getByRole('heading', {name: 'ShelfLife', exact: true}).waitFor();
    for (const item of expected.items) {
      await page.getByText(item.name, {exact: true}).first().waitFor({state: 'visible'});
    }

    const target = expected.target;
    const located = await itemScope(page, target.name);
    const initialText = await visibleQuantity(located.scope, target.quantity);
    if (target.unit) assert.ok(initialText.toLowerCase().includes(target.unit.toLowerCase()),
      'Imported unit must be visible');
    await page.screenshot({path: path.join(evidence,
      phase === 'consume' ? 'delivery-imported-desktop.png' : 'delivery-persisted-desktop.png'), fullPage: true});

    let changed = target;
    if (phase === 'consume') {
      // A real keyboard activation must cause the real local consume endpoint.
      // No page.evaluate mutation or test-only HTTP write replaces the UI.
      await located.action.focus();
      const [response] = await Promise.all([
        page.waitForResponse(response => {
          const url = new URL(response.url());
          return url.origin === base &&
            url.pathname === `/api/items/${target.id}/consume` &&
            response.request().method() === 'POST';
        }),
        located.action.press('Enter'),
      ]);
      assert.equal(response.status(), 200, await response.text());
      changed = await response.json();
      assert.ok(Number.isInteger(changed.quantity) && changed.quantity >= 0 &&
        changed.quantity < target.quantity, 'The UI must reduce the imported quantity');
      assert.deepEqual({...changed, quantity: target.quantity}, target,
        'Consumption must preserve every other imported field');
      await visibleQuantity(located.scope, changed.quantity);
      await page.screenshot({path: path.join(evidence, 'delivery-consumed-desktop.png'), fullPage: true});
    } else {
      // The second visit occurs only after the Python driver restarts the server.
      await page.setViewportSize({width: 375, height: 812});
      await page.getByText(target.name, {exact: true}).first().waitFor({state: 'visible'});
      await visibleQuantity(located.scope, target.quantity);
      await page.screenshot({path: path.join(evidence, 'delivery-persisted-phone.png'), fullPage: true});
    }

    assert.deepEqual(external, [], 'Every observed product request must remain on the local server');
    assert.deepEqual(errors, [], 'The integrated page must not have unhandled JavaScript errors');
    result = {phase, item: changed, rendered: await located.scope.innerText(),
      request_count: requests.length, external_requests: external, page_errors: errors};
  } catch (error) {
    if (page && !page.isClosed()) {
      try {
        await page.screenshot({path: path.join(evidence, `delivery-${phase}-failure.png`), fullPage: true});
      } catch (captureError) {
        console.error(`Failure screenshot unavailable: ${captureError.message}`);
      }
    }
    throw error;
  } finally {
    // Closing Edge comes first even if writing diagnostic evidence fails.
    try {
      if (browser) await browser.close();
    } finally {
      fs.writeFileSync(path.join(evidence, `delivery-${phase}-requests.json`),
        JSON.stringify({requests, external_requests: external, page_errors: errors}, null, 2));
    }
  }
  process.stdout.write(JSON.stringify(result) + '\n');
}

if (process.argv[2] === '--browser') {
  browserVisit(...process.argv.slice(3)).catch(error => {
    console.error(error.stack || error);
    process.exitCode = 1;
  });
} else {
  const result = spawnSync(PYTHON, ['-B', path.join(__dirname, 'fresh_folder.py')],
    {stdio: 'inherit', cwd: path.resolve(__dirname, '..', '..')});
  if (result.error) console.error(result.error.message);
  process.exitCode = result.status === null ? 1 : result.status;
}

