"""Only delivery mechanics: temporary folders and bounded child lifetimes."""

from contextlib import contextmanager
from pathlib import Path
import os
import subprocess
import tempfile
import time
import uuid


class ProcessFailure(RuntimeError):
    """A bounded process operation failed, with captured diagnostics."""


@contextmanager
def workspace():
    with tempfile.TemporaryDirectory(prefix="shelflife-delivery-") as folder:
        yield Path(folder)


class Child:
    def __init__(self, command, *, cwd):
        self.command = [str(part) for part in command]
        token = uuid.uuid4().hex
        self._out_path = Path(cwd) / f"child-{token}.stdout.log"
        self._err_path = Path(cwd) / f"child-{token}.stderr.log"
        self._out = self._out_path.open("wb")
        self._err = self._err_path.open("wb")
        try:
            self.process = subprocess.Popen(
                self.command, cwd=cwd, stdin=subprocess.DEVNULL,
                stdout=self._out, stderr=self._err,
            )
        except BaseException:
            self._out.close()
            self._err.close()
            raise

    @property
    def stdout(self):
        return self._out_path.read_text(encoding="utf-8", errors="replace")

    @property
    def stderr(self):
        return self._err_path.read_text(encoding="utf-8", errors="replace")

    def _failure(self, reason):
        return ProcessFailure(
            f"{reason}\ncommand: {self.command!r}\n"
            f"stdout:\n{self.stdout}\nstderr:\n{self.stderr}"
        )

    def stop(self):
        if self.process.poll() is None:
            if os.name == "nt":
                # Node owns Edge children. A timed-out Node command must not
                # leave its browser alive after the temporary folder is gone.
                killer = Path(os.environ["SystemRoot"]) / "System32" / "taskkill.exe"
                try:
                    result = subprocess.run(
                        [str(killer), "/PID", str(self.process.pid), "/T", "/F"],
                        capture_output=True, text=True, timeout=2,
                    )
                except (OSError, subprocess.TimeoutExpired) as error:
                    self.process.kill()
                    self.process.wait(timeout=2)
                    raise self._failure(f"process-tree shutdown failed: {error}") from error
                if result.returncode != 0 and self.process.poll() is None:
                    self.process.kill()
                    self.process.wait(timeout=2)
                    raise self._failure(f"process-tree shutdown failed: {result.stderr}")
            else:
                self.process.terminate()
            try:
                self.process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait(timeout=2)
        else:
            self.process.wait()

    def wait_ready(self, probe, *, timeout):
        deadline = time.monotonic() + timeout
        try:
            while True:
                code = self.process.poll()
                if code is not None:
                    raise self._failure(f"child exited with code {code} before readiness")
                if probe():
                    return
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise self._failure(f"readiness timed out after {timeout:g}s")
                time.sleep(min(0.05, remaining))
        except BaseException:
            self.stop()
            raise

    def finish(self, *, timeout):
        try:
            self.process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            self.stop()
            raise self._failure(f"command timed out after {timeout:g}s") from None
        return subprocess.CompletedProcess(
            self.command, self.process.returncode, self.stdout, self.stderr,
        )

    def __enter__(self):
        return self

    def __exit__(self, *_):
        try:
            self.stop()
        finally:
            self._out.close()
            self._err.close()
